import{_ as t,o as s,c as n,a5 as o}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"feature/authentication/3-2-2-sign-in-with-email/report3_spec.md","filePath":"feature/authentication/3-2-2-sign-in-with-email/report3_spec.md"}'),i={name:"feature/authentication/3-2-2-sign-in-with-email/report3_spec.md"};function r(a,e,l,c,g,u){return s(),n("div",null,[...e[0]||(e[0]=[o("<p><strong>3.2.2 Sign In with Email/Phone + Password</strong></p><p><strong>Function Trigger</strong></p><p>Begins when a Guest with an existing account visits /login and submits an identifier (email or phone number) together with a password.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: GUEST holding an existing account.</li><li><strong>Purpose</strong>: Authenticate with an email or phone number and a password, and obtain an access token plus a refresh token, unless two-factor authentication is enabled.</li><li><strong>Interface</strong>: Sign-in form with an identifier input (email or phone), a Password input, and a &quot;Forgot password&quot; link to Reset Password. Same screen carries the Google sign-in entry point.</li><li><strong>Data Processing</strong>: Resolves the identifier, checks account status, compares the password against the stored hash, records the sign-in, resolves the active workspace, and issues an access token plus a rotating refresh token; when 2FA is enabled, issues a challenge token instead.</li></ul><p><strong>Screen Layout</strong></p><p>Figure — Sign-in Screen:</p><ul><li>Identifier input (email or phone), Password input with reveal toggle, &quot;Forgot password&quot; link.</li><li>Submit button &quot;Sign in&quot;.</li><li>Divider &quot;Or continue with&quot;, Google sign-in button.</li><li>On success: stores access token, loads profile, navigates to Dashboard; toast <strong>MSG11</strong>.</li><li>When 2FA required: stores twoFactorToken in sessionStorage, navigates to /2fa-verify without storing any access token.</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: identifier (email or phone), password.</li><li><strong>Input optional</strong>: none.</li><li><strong>System data</strong>: userId, role, status, twoFactorEnabled, lastLoginAt, workspaceId, accessToken, refreshToken.</li><li><strong>Output</strong>: access token, token type, expiry, a flag for 2FA required, refresh token as HttpOnly cookie. When 2FA required: a two-factor challenge token instead of access/refresh tokens.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-05</strong>: Anti-enumeration. Unknown identifier, wrong password, or account with no password all return the same 401 INVALID_CREDENTIALS.</li><li><strong>BR-06</strong>: Suspended account -&gt; 403 ACCOUNT_SUSPENDED. Deactivated account -&gt; 403 ACCOUNT_DEACTIVATED. Checked before password comparison.</li><li><strong>BR-07</strong>: Identifier auto-detected as email or phone; email matched case-insensitively, phone normalized before lookup.</li><li><strong>BR-08</strong>: Access token JWT RS256, 15-minute TTL. Refresh token HttpOnly cookie only, 30-day TTL. When 2FA enabled, no access/refresh token issued at this step; a challenge token is returned instead.</li><li><strong>BR-12</strong>: Refresh token jti checked against a blacklist; a token issued before the latest password change is rejected. Refresh accepted only via cookie. Missing/stale token -&gt; 401 REFRESH_TOKEN_INVALID; blacklisted token -&gt; 401 REFRESH_TOKEN_BLACKLISTED. Successful refresh rotates the token.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>identifier empty -&gt; Display: <strong>MSG02</strong></li><li>password empty -&gt; Display: <strong>MSG02</strong></li><li>identifier not a valid email or phone format -&gt; Display: <strong>MSG04</strong></li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ol><li>The Guest opens /login and enters the identifier and password.</li><li>The system resolves the identifier to an account and checks the account status allows sign-in.</li><li>The system compares the submitted password with the stored hash.</li><li>With 2FA disabled, the system records the sign-in, resolves the active workspace, and issues an access token and a refresh token.</li><li>The system returns the tokens and sets the refresh token cookie.</li><li>The screen stores the access token, loads the profile, navigates to the Dashboard; toast <strong>MSG11</strong>.</li></ol></li><li><p><strong>Abnormal Cases</strong></p><ul><li>2.a1: Unknown identifier, wrong password, or no password (BR-05) -&gt; 401 INVALID_CREDENTIALS, toast <strong>MSG07</strong>. 2.a2: The Guest retries or uses &quot;Forgot password&quot;.</li><li>2.b1: Account status not ACTIVE/DEACTIVATED (BR-06) -&gt; 403 ACCOUNT_SUSPENDED, toast <strong>MSG09</strong>. 2.b2: The Guest contacts support.</li><li>2.c1: Account DEACTIVATED (BR-06) -&gt; 403 ACCOUNT_DEACTIVATED, toast <strong>MSG09</strong>. 2.c2: The Guest reactivates the account or contacts support.</li><li>4.a1: 2FA enabled (BR-08) -&gt; no access/refresh token issued; challenge token returned instead. 4.a2: The screen continues on the two-factor code screen.</li><li>5.a1: Refresh without cookie, or unusable/stale token (BR-12) -&gt; 401 REFRESH_TOKEN_INVALID, toast <strong>MSG22</strong>. 5.a2: Refresh with a blacklisted token (BR-12) -&gt; 401 REFRESH_TOKEN_BLACKLISTED, toast <strong>MSG22</strong>; either way the screen redirects to /login.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>The sign-in is recorded and last sign-in time updated.</li><li>An access token and refresh token cookie are issued when 2FA is disabled.</li><li>A two-factor challenge token, and no tokens, is issued when 2FA is enabled.</li></ul>",14)])])}const h=t(i,[["render",r]]);export{p as __pageData,h as default};
